const fs = require('fs');
const path = require('path');
const plan = JSON.parse(fs.readFileSync('/workspace/.exp_agent/round_01/plan.json', 'utf8'));
const entityName = (relativePath, location) => {
  const lines = fs.readFileSync(path.join('/workspace', relativePath), 'utf8').split(/\\r?\\n/);
  const source = (lines[location.line - 1] || '').trim();
  const match = source.match(/(?:@State\\s+)?(?:private\\s+)?([A-Za-z_"'$]['"\\w"'$]*)'"\\s*:/);
  if (match) return match[1];
  if (relativePath.endsWith('index/index.ets')) return 'Index.build Button onClick listener';
  return source;
};
const evidenceFor = (relativePath, location, entity) => {
  const lines = fs.readFileSync(path.join('/workspace', relativePath), 'utf8').split(/\\r?\\n/);
  const source = (lines[location.line - 1] || '').trim();
  return "'`${relativePath}:${location.line} contains ${entity} in the current source (${source})`;
};
const repairs = [];
for (const rule of plan.rules) {
  for (const file of rule.files) {
    const entities = [...new Set(file.locations.map(location => entityName(file.relative_path, location)))];
    const evidence = file.locations.map((location, index) => evidenceFor(file.relative_path, location, entities[Math.min(index, entities.length - 1)]));
    let transformation;
    if (rule.rule.endsWith('"'avoid-empty-callback')) {
      transformation = 'Removed the empty onClick callback from the Index build Button while retaining its existing text, styling, and layout.';
    } else if (rule.rule.endsWith('remove-container-without-property')) {
      transformation = 'Flattened the flagged single-child container wrapper while retaining the child content and all surrounding modifiers.';
    } else if (rule.rule.endsWith('remove-redundant-state-var')) {
      transformation = 'Removed @State from the flagged non-UI-associated fields while retaining each field name, type, initializer, and declaration.';
    } else {
      transformation = 'Removed @State from the flagged unchanged fields while retaining each field name, type, initializer, and declaration.';
    }
    repairs.push({
      rule: rule.rule,
      relative_path: file.relative_path,
      locations: file.locations,
      entities,
      evidence,
      transformation,
      status: 'repaired'
    });
  }
}
process.stdout.write(JSON.stringify({
  selected_rules: plan.rules.map(rule => rule.rule),
  entity_repairs: repairs,
  blocked: [],
  unresolved_external: []
}, null, 2));
